import { Scene } from '@aspose/3d-foss';
import { ObjLoadOptions, ObjImporter } from '@aspose/3d-foss';

// Create a new scene
const scene = new Scene();

// Import an OBJ file
const options = new ObjLoadOptions();
options.enableMaterials = true;
options.flipCoordinateSystem = false;
scene.open("model.obj", options);

// Access imported data
for (const node of scene.rootNode.childNodes) {
    if (node.entity) {
        const mesh = node.entity;
        console.log(`Mesh: ${node.name}`);
        console.log(`  Vertices: ${mesh.controlPoints.length}`);
        console.log(`  Polygons: ${mesh.polygonCount}`);
    }
}

import { Scene } from '@aspose/3d-foss';

const scene = new Scene();
scene.open('model.gltf');

for (const node of scene.rootNode.childNodes) {
  if (node.entity) {
    const mesh = node.entity;
    console.log(`Mesh: ${node.name}`);
    console.log(`  Vertices: ${mesh.controlPoints.length}`);
    console.log(`  Polygons: ${mesh.polygonCount}`);
  }
}

import * as THREE from '@aspose/3d-foss';

// Create a new scene
const scene = new THREE.Scene();

// Add a cube to the scene
const cube = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshStandardMaterial({ color: 0x44aa88 })
);
scene.rootNode.addChild(cube);

// Export the scene to GLTF 2.0
scene.save('output.gltf');
